contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters that let us call schedule, cancel and inspect timestamps.
    // params:
    // target: target address for single schedule
    // value: value for single schedule
    // data: calldata for single schedule
    // predecessor: predecessor id
    // salt: salt for hashing
    // delay: delay to schedule (must be >= minDelay to succeed)
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        require(true);

        // Read minDelay before scheduling
        uint256 minDelay = c.getMinDelay();

        // Compute id and ensure we can observe before-state
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        uint256 ts_before = c.getTimestamp(id);
        bool wasOpBefore = c.isOperation(id);

        // Attempt to schedule: it will revert if caller lacks PROPOSER_ROLE or delay < minDelay
        bool scheduled;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            scheduled = true;
        } catch {
            scheduled = false;
        }

        // After attempt, read timestamp and isOperation
        uint256 ts_after = c.getTimestamp(id);
        bool isOpAfter = c.isOperation(id);

        // If scheduling succeeded then:
        //  - timestamp must now be > 0 (operation exists)
        //  - isOperation must be true
        //  - timestamp should be at least block.timestamp + max(minDelay, delay)
        // We can't read block.timestamp from here; instead we assert a relation between ts_after and ts_before
        // General invariant we can assert for all inputs:
        //   If schedule succeeded then ts_after > ts_before and isOperation is true.
        //   If schedule failed then state did not become a new operation: isOperation stayed false or unchanged.
        // Additionally, verify that cancel (if schedule succeeded) can remove the operation: call cancel and then isOperation becomes false.

        bool cancelled = false;
        if (scheduled) {
            // now try cancelling
            try c.cancel(id) {
                cancelled = true;
            } catch {
                cancelled = false;
            }
        }

        bool isOpFinal = c.isOperation(id);

        // ASSERT: general rule combining the above behaviors
        // - If schedule succeeded then ts_after > ts_before and isOpAfter == true
        // - If schedule failed then either isOpAfter == wasOpBefore (no new op) or (rare) a new op wasn't observable
        // - If schedule succeeded and cancel succeeded then final isOperation must be false
        assert(
            (scheduled && ts_after > ts_before && isOpAfter) ||
            (!scheduled && isOpAfter == wasOpBefore) ||
            (scheduled && cancelled && !isOpFinal)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params let the caller attempt scheduling and cancelling a single operation.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        require(true);

        // Observe before-state
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        uint256 ts_before = c.getTimestamp(id);
        bool wasOpBefore = c.isOperation(id);

        // Attempt to schedule: must be a top-level call
        bool scheduled;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            scheduled = true;
        } catch {
            scheduled = false;
        }

        // Read after-state
        uint256 ts_after = c.getTimestamp(id);
        bool isOpAfter = c.isOperation(id);

        // If scheduled, attempt cancel as a separate top-level call
        bool cancelled = false;
        if (scheduled) {
            try c.cancel(id) {
                cancelled = true;
            } catch {
                cancelled = false;
            }
        }

        bool isOpFinal = c.isOperation(id);

        // General invariant:
        // - If scheduling succeeded then timestamp must have increased (strictly) and isOperation must be true.
        // - If scheduling then cancelling succeeded then final isOperation must be false.
        // - If scheduling reverted then no new operation became present (isOperation unchanged from before).
        assert(
            (scheduled && ts_after > ts_before && isOpAfter) ||
            (scheduled && cancelled && !isOpFinal) ||
            (!scheduled && isOpAfter == wasOpBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to schedule one operation and observe effects; all state-changing calls on c are top-level.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        require(true);

        // Compute id and observe before-state via view calls only
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        uint256 ts_before = c.getTimestamp(id);
        bool wasOpBefore = c.isOperation(id);

        // Attempt scheduling as a top-level call and capture whether it reverted
        bool scheduled;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            scheduled = true;
        } catch {
            scheduled = false;
        }

        // Read after-state via view calls only
        uint256 ts_after = c.getTimestamp(id);
        bool isOpAfter = c.isOperation(id);

        // Assertion: if scheduling succeeded then isOperation must be true and timestamp must have increased strictly;
        // if scheduling reverted then the operation presence and timestamp must be unchanged.
        assert(
            (scheduled && isOpAfter && ts_after > ts_before) ||
            (!scheduled && isOpAfter == wasOpBefore && ts_after == ts_before)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry exercising schedule and checking timestamp/pending status.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // require delay to be at least current min delay so schedule is allowed by that condition
        require(delay >= c.getMinDelay());

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        uint256 ts_before = c.getTimestamp(id);

        bool didRevert;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint256 ts_after = c.getTimestamp(id);
        bool pending_after = c.isOperationPending(id);

        // If schedule did not revert then timestamp must become > 0 and operation must be pending (timestamp > _DONE_TIMESTAMP)
        assert(didRevert || (ts_after > 0 && pending_after && ts_after > ts_before));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We require the caller (this contract) to have PROPOSER_ROLE before calling schedule.
    // The constructor of C by default does not grant PROPOSER_ROLE to this contract, so the
    // checker must pick inputs where this contract has that role (the checker can set up
    // deployment conditions). We also require delay >= getMinDelay() so schedule won't fail on delay.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // Precondition: caller (this contract) must have PROPOSER_ROLE and delay must be enough
        require(c.hasRole(c.PROPOSER_ROLE(), address(this)) , "must be proposer");
        require(delay >= c.getMinDelay(), "insufficient delay");

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // perform the scheduling call; this is the only state-changing call here
        bool didRevert;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Observe public view results
        uint256 ts = c.getTimestamp(id);
        bool isOp = c.isOperation(id);

        // General rule: if schedule did not revert (i.e., caller had permission and delay OK),
        // then the operation must be recorded and pending: timestamp > _DONE_TIMESTAMP (1) and isOperation true.
        assert(didRevert || (isOp && ts > 1));
    }

    receive() external payable {}
}
